mapper.update:
UPDATE sub_task
SET external_fallback_count = COALESCE(external_fallback_count, 0) + 1,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

mapper.select:
SELECT * FROM sub_task
WHERE assigned_agent_id = #{agentId}
  AND status IN ('ASSIGNED', 'IN_PROGRESS', 'REWORK')
  AND deleted = 0
ORDER BY id ASC
LIMIT #{limit}

SELECT * FROM sub_task
WHERE status = 'ASSIGNED'
  AND update_time < #{deadline}
  AND deleted = 0
ORDER BY update_time ASC
LIMIT #{limit}

SELECT st.id FROM sub_task st
WHERE st.status = 'PENDING'
  AND st.create_time < #{cutoff}
  AND st.deleted = 0
  AND NOT EXISTS (
      SELECT 1 FROM agent_execution_record aer
      WHERE aer.sub_task_id = st.id
  )
ORDER BY st.id ASC
LIMIT #{limit}

mapper.update:
UPDATE sub_task
SET attempt_total = COALESCE(attempt_total, 0) + 1,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

UPDATE sub_task
SET attempt_total = 0,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

UPDATE sub_task
SET depends_on = #{dependsOnJson}::jsonb,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0
